     1→import { type PropsWithChildren, useMemo } from 'react';
     2→
     3→interface ButtonProps extends PropsWithChildren {
     4→  variant?: 'neutral' | 'accent' | 'warning' | 'danger' | 'success' | 'transparent';
     5→  size?: 'regular' | 'narrow';
     6→  className?: string;
     7→  onClick?: () => void;
     8→}
     9→const Button: React.FC<ButtonProps> = ({
    10→  children,
    11→  variant = '',
    12→  size = 'regular',
    13→  className = '',
    14→  onClick,
    15→}) => {
    16→  const bgColor = useMemo(() => {
    17→    switch (variant) {
    18→      case 'neutral':
    19→        return 'bg-neutral-3';
    20→      case 'accent':
    21→        return 'bg-accent-9';
    22→      case 'warning':
    23→        return 'bg-warning-9';
    24→      case 'danger':
    25→        return 'bg-danger-9';
    26→      case 'success':
    27→        return 'bg-success-9';
    28→      case 'transparent':
    29→        return 'bg-transparent';
    30→      default:
    31→        return 'bg-neutral-9';
    32→    }
    33→  }, [variant]);
    34→
    35→  return (
    36→    <button
    37→      type="button"
    38→      onClick={onClick}
    39→      className={`rounded-md flex items-center justify-center cursor-pointer ${size === 'regular' && 'h-[32px] min-w-[32px] px-2'} ${bgColor} ${className}`}
    40→    >
    41→      {children}
    42→    </button>
    43→  );
    44→};
    45→
    46→export default Button;
