    11→const calcularDuracao = (inicio: string, fim?: string): number => {
    12→  const startDate = new Date(inicio);
    13→  const endDate = fim ? new Date(fim) : new Date();
    14→  const diffTime = Math.abs(endDate.getTime() - startDate.getTime());
    15→  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    16→};
