    18→const InitiativeList = () => {
    19→  const { initiatives, metadata, isLoading, isError, error } = useInitiatives();
    20→  const [filterText, setFilterText] = useState('');
    21→  const [selectedPhase, setSelectedPhase] = useState<string>('');
    22→  const [debouncedFilterText, setDebouncedFilterText] = useState('');
    23→  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
    24→
    25→  // Debounce filter text updates
    26→  const debouncedSetFilter = useMemo(
    27→    () => debounce((value: string) => setDebouncedFilterText(value), 300),
    28→    []
    29→  );
    30→
    31→  useEffect(() => {
    32→    debouncedSetFilter(filterText);
    33→    return () => {
    34→      debouncedSetFilter.cancel();
    35→    };
    36→  }, [filterText, debouncedSetFilter]);
    37→
    38→  // Memoize filtered initiatives
    39→  const filteredInitiatives = useMemo(() => {
    40→    return initiatives.filter((initiative) => {
    41→      const matchesSearch = initiative.IniTitulo.toLowerCase().includes(
    42→        debouncedFilterText.toLowerCase()
    43→      );
    44→      const matchesPhase = selectedPhase ? initiative.latestEvent.Fase === selectedPhase : true;
    45→      return matchesSearch && matchesPhase;
    46→    });
    47→  }, [initiatives, debouncedFilterText, selectedPhase]);
    48→
    49→  const toggleRow = (initiativeId: string) => {
